fun compareNumbers(a:List<Int>,b:List<Int>):Int {
    for(i in 0 until minOf(a.size,b.size)) {
        val c=a[i].compareTo(b[i]);
        if(c!=0)return c
    }
    return a.size.compareTo(b.size)
